# Look for patterns like 'January' followed by large numbers (debt)
import re

with open('/app/resources/treasury_bulletin_1969_10.txt', 'r') as f:
    for i, line in enumerate(f, 1):
        # Look for lines with January and a 6-digit number
        if 'January' in line:
            numbers = re.findall(r'\b(\d{5,6})\b', line)
            if len(numbers) >= 1:
                # Check if it's in a year context
                if any(str(y) in line for y in range(1969, 1981)):
                    print(f'Line {i}: {line[:200]}')"
